export interface CoreSpec {
  id: number;
  // position on the titan in arena units (x across, y up toward the titan, z height for rendering)
  x: number;
  y: number;
  z: number;
  // which beats (within a 64-beat phrase) the core lies open, as [startBeat, endBeat) windows
  windows: Array<[number, number]>;
  hp: number; // relative weight, only used for visuals (cracks)
}

export interface TitanSpec {
  seed: number;
  number: number; // the nth titan to wake
  name: string;
  epithet: string;
  archetype: Archetype;
  plate: Plate;
  bpm: number;
  beat: number; // seconds per beat
  root: number; // MIDI root note of its song
  mode: "aeolian" | "dorian" | "phrygian" | "lydian" | "mixolydian";
  scale: number; // body size multiplier
  limbs: number;
  segments: number;
  cores: CoreSpec[];
  origins: Array<{ x: number; y: number }>; // where attacks leave the body
  temperament: { aggression: number; trickery: number; patience: number }; // 0..1, shapes the attack plan
}

const SYL_A = ["va", "or", "ka", "thu", "mor", "sel", "ura", "bel", "zan", "ith", "gor", "ae", "nym", "har", "ost", "ul", "qe", "rhu", "sa", "dra", "ve", "lo", "mna", "tes"];
const SYL_B = ["sh", "r", "m", "th", "nd", "l", "k", "gh", "v", "s", "z", "rr", "dr", "x", "n"];
const SYL_C = ["ar", "un", "ex", "oth", "ael", "ir", "os", "ume", "ath", "is", "on", "ek", "aur", "ul", "yx", "em"];

const EPI_VERB = ["Swallows", "Unwrites", "Carries", "Remembers", "Drowns", "Hollows", "Gilds", "Unmakes", "Sings Down", "Keeps", "Devours", "Weighs", "Silences", "Mends"];
const EPI_OBJ = ["the Tides", "Small Gods", "the Last Bell", "Every Name", "the Lantern Roads", "Saints", "the Ninth Hour", "the Margins", "Cathedrals", "the Weather", "Broken Oaths", "the Moon's Debts", "Its Own Shadow", "the Quiet Hills"];
const EPI_NOUN = ["Mother of Hinges", "the Hollow Choir", "the Patient Flood", "Bishop of Ash", "the Unlettered", "the Gilt Wound", "Warden of the Ninth Gate", "the Long Psalm", "the Salt Regent", "the Inkwell Deep", "the Bell Without Tongue", "the Thousand-Eyed Hymn"];

function cap(s: string) {
  return s.charAt(0).toUpperCase() + s.slice(1);
}

export function titanName(seed: number): { name: string; epithet: string } {
  const r = rngFor("name", seed);
  const parts = r.int(2, 3);
  let n = r.pick(SYL_A);
  if (parts >= 2) n += r.pick(SYL_B) + r.pick(SYL_C);
  if (parts === 3 && n.length < 7) n += r.pick(SYL_B).slice(0, 1) + r.pick(SYL_C);
  const name = cap(n);
  const epithet = r.chance(0.55) ? `Who ${r.pick(EPI_VERB)} ${r.pick(EPI_OBJ)}` : r.pick(EPI_NOUN);
  return { name, epithet };
}

export const PHRASE_BEATS = 64; // 16 bars of 4
export const LOOP_PHRASES = 8; // the Canticle: 8 phrases then it repeats
export const LOOP_BEATS = PHRASE_BEATS * LOOP_PHRASES;

/** Arena: x in [-W/2, W/2], y in [0, H]; the titan towers beyond y = H. */
export const ARENA = { W: 16, H: 20, TOP: 20 };

/** A seed's anatomy (cheap: no need to build the whole titan). */
export function archetypeOf(seed: number): Archetype {
  return ARCHETYPES[hash32("arch", seed) % ARCHETYPES.length];
}

/**
 * The first of `candidate(0), candidate(1), ...` whose archetype differs from `avoid` (the titan just felled),
 * so a fall is always followed by a different body. Deterministic; candidate(0) is kept whenever it already
 * differs, so seeds chosen before this rule are unchanged.
 */
export function seedUnlike(candidate: (k: number) => number, avoid?: Archetype | null): number {
  let s = candidate(0) >>> 0;
  for (let k = 1; avoid && archetypeOf(s) === avoid && k < 64; k++) s = candidate(k) >>> 0;
  return s;
}

export function makeTitan(seed: number, number: number): TitanSpec {
  const r = rngFor("titan", seed);
  const archetype = archetypeOf(seed);
  const plate = PLATES[hash32("plate", seed) % PLATES.length];
  const bpm = r.int(23, 33) * 4; // 92..132, multiple of 4
  const modes = ["aeolian", "dorian", "phrygian", "lydian", "mixolydian"] as const;
  const mode = r.weighted(modes, [4, 3, 2, 1, 1]);
  const root = 36 + r.int(0, 11);
  const { name, epithet } = titanName(seed);
  const scale = r.range(0.9, 1.15);

  const coreCount = archetype === "swarmheart" ? 3 : r.int(3, 5);
  const cores: CoreSpec[] = [];
  for (let i = 0; i < coreCount; i++) {
    // spread evenly across the titan's front, never overlapping (≥ 2.4 units apart)
    const t = coreCount === 1 ? 0.5 : i / (coreCount - 1);
    const span = Math.max(2.4 * (coreCount - 1), r.range(8.5, 11));
    const x = (t - 0.5) * span + r.range(-0.35, 0.35);
    const y = ARENA.TOP + r.range(0.6, 2.4);
    const z = r.range(2.5, 6.5);
    // each core opens in 2..3 windows per phrase, each 6..12 beats, on bar lines
    const windows: Array<[number, number]> = [];
    const n = r.int(2, 3);
    const slots = r.shuffle([0, 1, 2, 3, 4, 5, 6, 7].slice());
    for (let k = 0; k < n; k++) {
      const start = slots[k] * 8 + (r.chance(0.5) ? 0 : 4);
      const len = r.pick([6, 8, 8, 12]);
      windows.push([start, Math.min(PHRASE_BEATS, start + len)]);
    }
    windows.sort((a, b) => a[0] - b[0]);
    cores.push({ id: i, x, y, z, windows, hp: r.range(0.7, 1.3) });
  }

  const originCount = r.int(3, 6);
  const origins: Array<{ x: number; y: number }> = [];
  for (let i = 0; i < originCount; i++) {
    const t = originCount === 1 ? 0.5 : i / (originCount - 1);
    origins.push({ x: (t - 0.5) * r.range(8, 13), y: ARENA.TOP + r.range(0.2, 1.4) });
  }
  origins.push({ x: 0, y: ARENA.TOP + 0.6 }); // the mouth, always central

  return {
    seed,
    number,
    name,
    epithet,
    archetype,
    plate,
    bpm,
    beat: 60 / bpm,
    root,
    mode,
    scale,
    limbs: archetype === "strider" ? r.int(4, 6) : archetype === "bloom" ? r.int(6, 9) : r.int(2, 4),
    segments: r.int(9, 16),
    cores,
    origins,
    temperament: { aggression: r.next(), trickery: r.next(), patience: r.next() },
  };
}

export type Stage = 0 | 1 | 2; // Calm, Wrath, Ruin
export const STAGE_NAMES = ["Calm", "Wrath", "Ruin"] as const;
export function stageFor(hpFrac: number): Stage {
  return hpFrac > 0.66 ? 0 : hpFrac > 0.33 ? 1 : 2;
}

/** Is a core open at absolute beat b (beats since the titan woke)? Ruin opens cores a little longer. */
export function coreOpen(core: CoreSpec, beatAbs: number, stage: Stage): boolean {
  const inPhrase = ((beatAbs % PHRASE_BEATS) + PHRASE_BEATS) % PHRASE_BEATS;
  const extra = stage === 2 ? 2 : 0;
  for (const [a, b] of core.windows) if (inPhrase >= a && inPhrase < b + extra) return true;
  return false;
}

export function anyCoreOpen(spec: TitanSpec, beatAbs: number, stage: Stage): boolean {
  for (const c of spec.cores) if (coreOpen(c, beatAbs, stage)) return true;
  return false;
}
